namespace fs=std::filesystem;
static void need(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
static std::vector<std::string> split(const std::string& s){std::istringstream f(s);std::string x;std::vector<std::string> v;while(std::getline(f,x,'\t'))v.push_back(x);return v;}
static std::string read(const fs::path& p){std::ifstream f(p);need(bool(f),"read "+p.string());std::ostringstream s;s<<f.rdbuf();return s.str();}
static void write(const fs::path& p,const std::string& s){std::ofstream f(p);need(bool(f),"write "+p.string());f<<s;need(bool(f),"write completion");}
static int integer(const std::string& s){size_t used=0;int n=std::stoi(s,&used);need(used==s.size(),"integer token");return n;}
static bool prime(int n){if(n<2)return false;for(int d=2;d<=n/d;++d)if(n%d==0)return false;return true;}
struct Cut{int L,s,inc;std::array<int,4> gap;};
struct Coverage{int positive=0,min=10000,max=-10000,at691=0,at5000=0;};
static std::vector<std::pair<int,int>> intervals(const std::vector<Cut>& cs,bool inclusive){std::vector<std::pair<int,int>> out;int first=-1;for(const auto& c:cs){bool yes=inclusive?c.inc:c.s;if(yes&&first<0)first=c.L;if(!yes&&first>=0){out.emplace_back(first,c.L-1);first=-1;}}if(first>=0)out.emplace_back(first,cs.back().L);return out;}
static void json_intervals(std::ostream& out,const std::vector<std::pair<int,int>>& v){out<<'[';for(size_t i=0;i<v.size();++i){if(i)out<<',';out<<'['<<v[i].first<<','<<v[i].second<<']';}out<<']';}
static std::string percentage(int numerator,int denominator){std::ostringstream s;s<<std::fixed<<std::setprecision(4)<<100.0*static_cast<double>(numerator)/denominator;return s.str();}
int main(int argc,char** argv){try{
 need(argc==4,"summarize RUN COHORT FRESH_DERIVED");fs::path run=argv[1],out=argv[3];need(!fs::exists(out),"fresh derived directory");
 need(read(run/"verification.json").find("\"all_five_files_equal\":true")!=std::string::npos,"independent verification receipt");
 need(read(run/"completion.json").find("\"completed\":true")!=std::string::npos,"complete native phase record");
 std::istringstream cf(read(run/"results/cutoffs.tsv"));std::string line;need(bool(std::getline(cf,line))&&split(line).size()==7,"cutoff header");std::vector<Cut> cuts;std::array<Coverage,4> coverage{};
 int strictN=0,inclusiveN=0,strictEffective=0,inclusiveEffective=0,effectiveN=0;
 while(std::getline(cf,line)){auto c=split(line);need(c.size()==7,"cutoff width");Cut r;r.L=integer(c[0]);r.s=integer(c[1]);r.inc=integer(c[2]);need(r.L==100+static_cast<int>(cuts.size()),"complete ordered integer grid");need((r.s==0||r.s==1)&&(r.inc==0||r.inc==1),"boolean flags");bool all=true;for(size_t j=0;j<4;++j){r.gap[j]=integer(c[j+3]);auto& v=coverage[j];v.positive+=r.gap[j]>0;v.min=std::min(v.min,r.gap[j]);v.max=std::max(v.max,r.gap[j]);if(r.L==691)v.at691=r.gap[j];if(r.L==5000)v.at5000=r.gap[j];all=all&&r.gap[j]>0;}need(r.s==static_cast<int>(all),"strict flag versus four margins");strictN+=r.s;inclusiveN+=r.inc;if(r.L==100||prime(r.L)){++effectiveN;strictEffective+=r.s;inclusiveEffective+=r.inc;}cuts.push_back(r);}
 need(cuts.size()==4901&&effectiveN==645,"full range and effective family");
 int labels=0,strictLabels=0,inclusiveLabels=0,fixedLabels=0,oldLabels=0,expandedOnly=0,oldOnly=0,both=0,cumulativeLabels=0;
 std::istringstream cal(read(run/"results/calibration.tsv"));need(bool(std::getline(cal,line)),"calibration header");std::set<int> masks;
 while(std::getline(cal,line)){auto c=split(line);need(c.size()==5,"calibration width");int m=integer(c[0]),s=integer(c[1]),f=integer(c[2]),i=integer(c[3]),o=integer(c[4]);need(masks.insert(m).second,"unique label masks");need((s==0||s==1)&&(f==0||f==1)&&(i==0||i==1)&&(o==0||o==1),"label flags");++labels;strictLabels+=s;fixedLabels+=f;inclusiveLabels+=i;oldLabels+=o;expandedOnly+=s&&!o;oldOnly+=o&&!s;both+=s&&o;cumulativeLabels+=s||o;}
 need(labels==4480&&oldLabels==23&&fixedLabels==1,"full label inventory and prior reproduction");
 const std::string nativeSummary=read(run/"results/summary.json");
 for(const auto& x:std::vector<std::pair<std::string,int>>{{"strict_search_success_assignments",strictLabels},{"inclusive_search_success_assignments",inclusiveLabels},{"strict_fixed691_success_assignments",fixedLabels},{"previous_search_success_assignments",oldLabels}})need(nativeSummary.find("\""+x.first+"\":"+std::to_string(x.second)+",")!=std::string::npos,"native headline agreement");
 auto strictIntervals=intervals(cuts,false),inclusiveIntervals=intervals(cuts,true);
 fs::create_directories(out);std::ostringstream summary;summary<<"{\n  \"kind\":\"verified-expanded-cutoff-description/v1\",\n  \"rows\":21,\"integer_cutoffs\":4901,\"effective_cutoffs\":645,\n  \"strict_success_integer_cutoffs\":"<<strictN<<",\"strict_success_effective_cutoffs\":"<<strictEffective<<",\n  \"strict_integer_coverage_percent\":"<<percentage(strictN,4901)<<",\n  \"strict_effective_coverage_percent\":"<<percentage(strictEffective,645)<<",\n  \"strict_integer_success_intervals\":";json_intervals(summary,strictIntervals);summary<<",\n  \"inclusive_success_integer_cutoffs\":"<<inclusiveN<<",\"inclusive_success_effective_cutoffs\":"<<inclusiveEffective<<",\n  \"inclusive_integer_success_intervals\":";json_intervals(summary,inclusiveIntervals);summary<<",\n  \"label_assignments\":4480,\"strict_search_success_assignments\":"<<strictLabels<<",\"strict_search_fraction_percent\":"<<percentage(strictLabels,4480)<<",\n  \"inclusive_search_success_assignments\":"<<inclusiveLabels<<",\"strict_fixed691_success_assignments\":"<<fixedLabels<<",\n  \"old_search_success_assignments\":"<<oldLabels<<",\"expanded_only_assignments\":"<<expandedOnly<<",\"old_only_assignments\":"<<oldOnly<<",\"both_families_assignments\":"<<both<<",\n  \"cumulative_2_5000_success_assignments\":"<<cumulativeLabels<<",\"cumulative_2_5000_percent\":"<<percentage(cumulativeLabels,4480)<<",\n  \"independent_raw_verification\":\"PASS\",\"negative_control_refusals\":3,\n  \"historical_use_established\":false,\"ECDLP_advantage_established\":false,\n  \"new_curves\":0,\"random_baseline_accepted\":0,\"S3_checkpoint_claimed\":false,\"timing_admitted\":false\n}\n";write(out/"analysis.json",summary.str());
 const std::array<int,4> bits{192,224,239,256};std::ostringstream table,tex;
 table<<"field_bits\tpositive_margin_cutoffs\ttotal_cutoffs\tcoverage_percent\tminimum_margin\tmaximum_margin\tmargin691\tmargin5000\n";
 for(size_t j=0;j<4;++j){const auto& c=coverage[j];table<<bits[j]<<'\t'<<c.positive<<"\t4901\t"<<percentage(c.positive,4901)<<'\t'<<c.min<<'\t'<<c.max<<'\t'<<c.at691<<'\t'<<c.at5000<<'\n';tex<<bits[j]<<" & "<<c.positive<<" & "<<percentage(c.positive,4901)<<" & "<<c.at691<<" & "<<c.at5000<<" \\\\\n";}
 write(out/"field-coverage.tsv",table.str());write(out/"field-coverage.tex",tex.str());
 struct Endpoint{int bits;std::string role;std::array<int,3> primary{},last{};bool gotP=false,gotL=false;};
 std::map<std::string,Endpoint> end;std::istringstream cohort(read(argv[2]));std::vector<std::string> order;
 while(std::getline(cohort,line)){if(line.empty()||line[0]=='#')continue;auto c=split(line);need(c.size()==9,"cohort");Endpoint e;e.bits=integer(c[1]);e.role=c[2];need(e.role=="published"||e.role=="skipped","role");need(end.emplace(c[0],e).second,"unique cohort");order.push_back(c[0]);}need(end.size()==21,"all21cohort identities");
 std::istringstream profiles(read(run/"results/profiles.tsv"));need(bool(std::getline(profiles,line)),"profile header");int profileRows=0;
 while(std::getline(profiles,line)){auto c=split(line);need(c.size()==7,"profile width");++profileRows;auto it=end.find(c[0]);need(it!=end.end()&&integer(c[1])==it->second.bits&&c[2]==it->second.role,"profile identity");int L=integer(c[3]);std::array<int,3> v{integer(c[4]),integer(c[5]),integer(c[6])};need(v[0]+v[1]==v[2],"strict plus ramified equals inclusive");if(L==691){need(!it->second.gotP,"unique primary endpoint");it->second.primary=v;it->second.gotP=true;}if(L==5000){need(!it->second.gotL,"unique last endpoint");it->second.last=v;it->second.gotL=true;}}
 need(profileRows==102921,"all21by4901profile cells");std::ostringstream ep,eptex;ep<<"label\tbits\trole\tstrict691\tramified691\tinclusive691\tstrict5000\tramified5000\tinclusive5000\n";
 for(const auto& id:order){const auto& e=end.at(id);need(e.gotP&&e.gotL,"every endpoint");ep<<id<<'\t'<<e.bits<<'\t'<<e.role;for(int v:e.primary)ep<<'\t'<<v;for(int v:e.last)ep<<'\t'<<v;ep<<'\n';eptex<<"\\texttt{"<<id<<"} & "<<(e.role=="published"?"P":"U");for(int v:e.primary)eptex<<" & "<<v;for(int v:e.last)eptex<<" & "<<v;eptex<<" \\\\\n";}write(out/"endpoints.tsv",ep.str());write(out/"endpoints.tex",eptex.str());
 std::ostringstream macros;macros<<"\\newcommand{\\StrictIntegerCount}{"<<strictN<<"}\n\\newcommand{\\StrictIntegerPct}{"<<percentage(strictN,4901)<<"}\n\\newcommand{\\StrictEffectiveCount}{"<<strictEffective<<"}\n\\newcommand{\\StrictLabels}{"<<strictLabels<<"}\n\\newcommand{\\StrictLabelsPct}{"<<percentage(strictLabels,4480)<<"}\n\\newcommand{\\InclusiveLabels}{"<<inclusiveLabels<<"}\n\\newcommand{\\InclusiveIntegerCount}{"<<inclusiveN<<"}\n";write(out/"numbers.tex",macros.str());
 std::ostringstream plot,svg;plot<<"{\"kind\":\"recorded-cutoff-margin-plot/v1\",\"selection\":\"100-step grid plus691, all sign-change boundaries, extrema and global success boundaries\",\"full_grid_retained\":true,\"series\":[";
 svg<<std::fixed<<std::setprecision(1)<<"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1000\" height=\"650\" viewBox=\"0 0 1000 650\"><style>text{font-family:DejaVu Sans,sans-serif;font-size:16px;fill:#17202a}.axis{stroke:#88939d;fill:none}.zero{stroke:#a33;stroke-dasharray:4 4}.line{stroke:#164e8b;stroke-width:2;fill:none}</style><rect width=\"1000\" height=\"650\" fill=\"white\"/><text x=\"500\" y=\"27\" text-anchor=\"middle\" style=\"font-size:21px\">Strict separation margin across the expanded cutoff range</text>";
 for(size_t j=0;j<4;++j){std::set<int> shown{100,691,5000};for(int L=100;L<=5000;L+=100)shown.insert(L);int argmin=100,argmax=100;for(size_t k=1;k<cuts.size();++k){if(cuts[k].gap[j]<cuts[static_cast<size_t>(argmin-100)].gap[j])argmin=cuts[k].L;if(cuts[k].gap[j]>cuts[static_cast<size_t>(argmax-100)].gap[j])argmax=cuts[k].L;if((cuts[k].gap[j]>0)!=(cuts[k-1].gap[j]>0)){shown.insert(cuts[k-1].L);shown.insert(cuts[k].L);}}shown.insert(argmin);shown.insert(argmax);for(auto v:strictIntervals)for(int L:{v.first-1,v.first,v.second,v.second+1})if(L>=100&&L<=5000)shown.insert(L);
  if(j){plot<<',';}plot<<"{\"bits\":"<<bits[j]<<",\"points\":[";bool first=true;for(int L:shown){if(!first)plot<<',';first=false;plot<<'['<<L<<','<<cuts[static_cast<size_t>(L-100)].gap[j]<<']';}plot<<"]}";
  double x0=72+(j%2)*485,y0=68+(j/2)*274,w=392,h=174;int low=std::min(0,coverage[j].min)-1,high=std::max(0,coverage[j].max)+1;auto x=[&](int L){return x0+(L-100)*w/4900;};auto y=[&](int v){return y0+h-(v-low)*h/(high-low);};
  svg<<"<text x=\""<<x0+w/2<<"\" y=\""<<y0-14<<"\" text-anchor=\"middle\" style=\"font-weight:bold\">"<<bits[j]<<"-bit field</text><rect class=\"axis\" fill=\"none\" stroke=\"#88939d\" x=\""<<x0<<"\" y=\""<<y0<<"\" width=\""<<w<<"\" height=\""<<h<<"\"/><path class=\"zero\" fill=\"none\" stroke=\"#a33\" stroke-dasharray=\"4 4\" d=\"M"<<x0<<' '<<y(0)<<'H'<<x0+w<<"\"/><path stroke=\"#888\" stroke-dasharray=\"3 4\" d=\"M"<<x(691)<<' '<<y0<<'V'<<y0+h<<"\"/><polyline class=\"line\" fill=\"none\" stroke=\"#164e8b\" stroke-width=\"2\" points=\"";for(int L:shown)svg<<x(L)<<','<<y(cuts[static_cast<size_t>(L-100)].gap[j])<<' ';svg<<"\"/>";
  for(int L:{100,1000,2000,3000,4000,5000})svg<<"<text x=\""<<x(L)<<"\" y=\""<<y0+h+23<<"\" text-anchor=\"middle\">"<<L<<"</text>";
  for(int v:std::set<int>{low,0,high})svg<<"<text x=\""<<x0-10<<"\" y=\""<<y(v)+5<<"\" text-anchor=\"end\">"<<v<<"</text>";
  svg<<"<circle cx=\""<<x(691)<<"\" cy=\""<<y(coverage[j].at691)<<"\" r=\"3.3\" fill=\"#164e8b\"/>";
 }
 plot<<"]}\n";svg<<"<text transform=\"translate(20 310) rotate(-90)\" text-anchor=\"middle\">min(unpublished) - max(published), in split primes</text><text x=\"500\" y=\"608\" text-anchor=\"middle\">Cutoff L (decimal); all four margins must be positive</text><text x=\"500\" y=\"635\" text-anchor=\"middle\" style=\"font-size:14px\">Displayed recorded cutoffs include every sign-change boundary; all 4901 grid points are retained.</text></svg>\n";write(out/"figure-data.json",plot.str());write(out/"cutoff-margins.svg",svg.str());
 std::string diagram="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1000\" height=\"170\" viewBox=\"0 0 1000 170\"><style>text{font:16px DejaVu Sans,sans-serif;fill:#17202a}.b{fill:#edf3fa;stroke:#356}.a{stroke:#356;stroke-width:2}</style><rect class=\"b\" fill=\"#edf3fa\" stroke=\"#356\" x=\"10\" y=\"15\" width=\"210\" height=\"65\" rx=\"6\"/><text x=\"115\" y=\"41\" text-anchor=\"middle\">21 certified curve rows</text><text x=\"115\" y=\"65\" text-anchor=\"middle\">fixed p,n and labels</text><path class=\"a\" fill=\"none\" stroke=\"#356\" stroke-width=\"2\" d=\"M220 47h30m-8-6 8 6-8 6\"/><rect class=\"b\" fill=\"#edf3fa\" stroke=\"#356\" x=\"250\" y=\"15\" width=\"220\" height=\"65\" rx=\"6\"/><text x=\"360\" y=\"41\" text-anchor=\"middle\">14,028 odd characters</text><text x=\"360\" y=\"65\" text-anchor=\"middle\">4,901 cutoff outcomes</text><path class=\"a\" fill=\"none\" stroke=\"#356\" stroke-width=\"2\" d=\"M470 47h30m-8-6 8 6-8 6\"/><rect class=\"b\" fill=\"#edf3fa\" stroke=\"#356\" x=\"500\" y=\"15\" width=\"220\" height=\"65\" rx=\"6\"/><text x=\"610\" y=\"41\" text-anchor=\"middle\">4,480 label assignments</text><text x=\"610\" y=\"65\" text-anchor=\"middle\">five files reconstructed</text><path class=\"a\" fill=\"none\" stroke=\"#356\" stroke-width=\"2\" d=\"M720 47h30m-8-6 8 6-8 6\"/><rect class=\"b\" fill=\"#edf3fa\" stroke=\"#356\" x=\"750\" y=\"15\" width=\"235\" height=\"65\" rx=\"6\"/><text x=\"867\" y=\"41\" text-anchor=\"middle\">Independent native check</text><text x=\"867\" y=\"65\" text-anchor=\"middle\">3 corruptions refused</text><text x=\"500\" y=\"125\" text-anchor=\"middle\" style=\"font-weight:bold\">Verified finite computation</text><text x=\"500\" y=\"152\" text-anchor=\"middle\">Historical selection, random-curve percentiles and an ECDLP advantage remain unestablished.</text></svg>\n";
 write(out/"evidence-boundary.svg",diagram);std::cout<<summary.str();return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
